{
  "core_question": "How to design a defensible first version of an AI sepsis‑risk decision support tool for a 12‑hospital health system covering clinical safety, legal/regulatory exposure, and financial structure.",
  "rationale": "Clinical safety requires evidence‑based validation and workflow integration; legal expertise is needed to navigate FDA SaMD classification, HIPAA, and liability; finance must model subscription economics, reimbursement, and ROI for the health system.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "For a per‑seat annual subscription AI tool that surfaces sepsis risk scores in an EHR across 12 hospitals, what clinical safety measures—including data quality controls, model validation protocols, explainability requirements, and real‑time monitoring—should be implemented to ensure patient safety and provider trust?",
    "legal": "Given the same AI CDS system, what FDA regulatory pathway (e.g., Class II SaMD with premarket notification 510(k) or De Novo), HIPAA compliance steps, data privacy safeguards, and liability mitigation strategies should the health system adopt to minimize legal exposure?",
    "finance": "What subscription pricing model, cost‑benefit analysis, reimbursement considerations, and ROI metrics should the health system use to structure a defensible per‑seat annual fee for this AI sepsis risk tool?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "FDA SaMD AI/ML guidance (2023), CMS coverage policies for CDS tools, recent HIPAA enforcement trends"
}
